out={}
for key,r in records.items():
 i=int(key);status,depth,attempt,gap,body=notes[i];ar=r['source_url'].split('/')[-1]
 src=[{'url':x['url'],'receipt':x['receipt'],'status':x.get('status'),'sha256':x.get('sha256'),'error':x.get('error')} for x in receipts if ar in x['url']]
 out[key]={**r,'outcome':status,'review_depth':depth,'primary_body':body,'mathematical_attempts':attempt,'remaining_lemmas_or_gaps':gap,'credit':0,'credit_risk':'No qualifying new full-scope solution. '+('Known result; zero credit.' if 'published' in status else 'No novelty or formal endpoint claimed.'),'source_receipts':src,'historical_screen':'outputs/history-relevant.txt; outputs/inherited-families.json; TASK.txt family warnings','registry_screen':'outputs/registry-screen.json','literature_searches':[f'outputs/web-search-{j:02d}.json' for j in range(1,13)],'version_review_limit':'All versions listed on the retrieved arXiv abstract were downloaded and converted. Relevant current statements were read. Historic bodies were not comprehensively compared line by line; version-of-record coverage is explicitly incomplete where only metadata/access receipts exist.','lean':{'endpoint':None,'status':'No qualifying endpoint; no Lean invocation or dummy theorem.'}}
assert len(out)==20
(D/'results.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n')
(D/'outputs/http-manifest.json').write_text(json.dumps(receipts,indent=2)+'\n')
