for r in receipts:
 if '/git/trees/' in r['url'] and 'lean-pool' not in r['url'] and r.get('status')==200:
  t=json.loads((D/r['receipt']).with_name('body').read_text());o['other_registries'].append({'url':r['url'],'receipt':r['receipt'],'sha':t['sha'],'truncated':t.get('truncated'),'path_count':len(t['tree']),'path_matches':[x['path'] for x in t['tree'] if pattern.search(x['path'])]})
